def backfill_multi_complex(apps, schema_editor):
    """Da continuidad a los datos existentes sin romper cuentas ni accesos.

    - Si ya hay torneos/canchas, crea un complejo principal y se los asigna.
    - Vincula a todo el staff activo con ese complejo.
    - Reconstruye las entradas (torneo, jugador) desde inscripciones y zonas.
    """
    Complex = apps.get_model("core", "Complex")
    Tournament = apps.get_model("core", "Tournament")
    Court = apps.get_model("core", "Court")
    Registration = apps.get_model("core", "Registration")
    ZoneTeam = apps.get_model("core", "ZoneTeam")
    Team = apps.get_model("core", "Team")
    TournamentPlayer = apps.get_model("core", "TournamentPlayer")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))

    if not Tournament.objects.exists() and not Court.objects.exists():
        return

    main_complex, _ = Complex.objects.get_or_create(
        slug="complejo-principal",
        defaults={"name": "Complejo principal", "is_active": True},
    )
    Tournament.objects.filter(complex__isnull=True).update(complex=main_complex)
    Court.objects.filter(complex__isnull=True).update(complex=main_complex)
    staff_ids = list(User.objects.filter(is_staff=True, is_active=True).values_list("id", flat=True))
    if staff_ids:
        main_complex.users.add(*staff_ids)

    for tournament in Tournament.objects.all():
        team_ids = set(
            Registration.objects.filter(tournament=tournament)
            .exclude(status="cancelled")
            .values_list("team_id", flat=True)
        )
        team_ids.update(ZoneTeam.objects.filter(zone__tournament=tournament).values_list("team_id", flat=True))
        for team in Team.objects.filter(pk__in=team_ids):
            for player_id in {team.player1_id, team.player2_id}:
                if player_id is None:
                    continue
                if not TournamentPlayer.objects.filter(tournament=tournament, player_id=player_id).exists():
                    TournamentPlayer.objects.create(
                        tournament=tournament, player_id=player_id, team_id=team.pk
                    )


